package main

import (
 "encoding/json"
 "fmt"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
 "bytes"
 "github.com/KogenAI/kogen-loop/provider"
 "github.com/KogenAI/kogen-loop/sys"
 "github.com/KogenAI/kogen-setup/setup"
 "github.com/KogenAI/kogen-verification/verify"
)

func main() {
 root := os.Args[1]
 temp, err := os.MkdirTemp("", "init-control-")
 if err != nil { panic(err) }; defer os.RemoveAll(temp)
 tree := filepath.Join(temp, "tree")
 git := func(dir string, args ...string) string {
  c := exec.Command("git", args...); c.Dir = dir
  b, e := c.CombinedOutput(); if e != nil { panic(fmt.Sprintf("%v: %s", e,b)) }; return strings.TrimSpace(string(b))
 }
 git(root, "clone", "-q", "--no-hardlinks", root, tree)
 git(tree, "config", "user.name", "Init Fixture")
 git(tree, "config", "user.email", "init@example.invalid")
 git(tree, "config", "commit.gpgsign", "false")
 git(tree, "config", "core.hooksPath", "/dev/null")
 s := sys.NewWith(os.Environ(), tree)
 var diagnostics bytes.Buffer
 s.Stdout, s.Stderr = &diagnostics, &diagnostics
 code, runErr := setup.Init(s.Context(), s, setup.InitInput{Client: provider.NewClient("dev"), Tools: verify.Tools{Node: os.Getenv("KOGEN_NODE"), Quint: os.Getenv("KOGEN_QUINT"), Cucumber: os.Getenv("KOGEN_CUCUMBER")}})
 fmt.Fprint(os.Stderr, strings.ReplaceAll(diagnostics.String(), tree, root))
 var message *string
 var configuration any
 if runErr != nil { v := runErr.Error(); message = &v }
 if code == 0 {
  git(root, "fetch", "-q", tree, "HEAD")
  head := git(root, "rev-parse", "FETCH_HEAD")
  git(root, "update-ref", "HEAD", head)
  git(root, "read-tree", head)
  for _, p := range []string{".kogen/project.yaml", ".kogen/models.yaml", ".gitignore", "features/steps/README.md"} {
   b, e := os.ReadFile(filepath.Join(tree,p)); if e != nil { panic(e) }
   target := filepath.Join(root,p); if e := os.MkdirAll(filepath.Dir(target),0755); e != nil { panic(e) }; if e := os.WriteFile(target,b,0644); e != nil { panic(e) }
  }
  b, e := os.ReadFile(filepath.Join(root,".kogen/project.yaml")); if e != nil { panic(e) }
  configuration = map[string]string{"path":".kogen/project.yaml","content":string(b)}
 }
 if e := json.NewEncoder(os.Stdout).Encode(map[string]any{"exit":code,"configuration":configuration,"error":message}); e != nil { panic(e) }
 os.Exit(code)
}

